import {getPlan,REVISION,SOURCES,SOURCE_DIVERGENCES,WALL_RAISE} from './specification.js';
import {sourceLedger} from './client-tools.js';
import {CATALOGUE_OPTIONS,TECHNICAL_FACTS,SOURCE_LAYOUTS} from './technical-data.js';
import {REFERENCE_VIDEOS} from './reference-videos.js';
import {LAYERS} from './model-layers.js';
import {configurationReference} from './portfolio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(value,digits=3)=>Number(value).toLocaleString('pt-PT',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const valueText=(value,unit)=>`${Array.isArray(value)?value.join(unit==='mm'?' × ':' · '):value===false?'Não representada':value===null?'Não indicado':value}${unit?' '+unit:''}`;
const sourceLink=source=>source?.file?`<a href="${esc(source.file)}${source.page?'#page='+source.page:''}" target="_blank" rel="noopener">${source.page?'Catálogo · p. '+(source.pages?.join('–')||source.page):'Plantas originais'} ↗</a>`:'Indicação do projecto';
const headings={confirmed:'Confirmado na fonte',estimated:'Estimado na maquete',missing:'Por documentar'};
function dimensionRows(dimensions){return dimensions.map(d=>`<tr data-measure="${d.id}"><th scope="row">${esc(d.label)}</th><td data-label="Valor na fonte">${d.provided===null?'Não cotada':number(d.provided)+' '+d.unit}</td><td data-label="Valor na maquete">${d.modelled===null?'—':number(d.modelled)+' '+d.unit}</td><td data-label="Estado"><span class="status-label ${d.status}">${headings[d.status]}</span></td><td data-label="Origem e limite">${esc(d.source)}${d.note?'<small>'+esc(d.note)+'</small>':''}</td></tr>`).join('');}
function optionCard(option){const price=option.cataloguePrice,amount=price.value===null?'Preço não indicado':Number(price.value).toLocaleString('pt-PT',{style:'currency',currency:'EUR',maximumFractionDigits:0});return `<article class="technical-option" data-option="${esc(option.id)}"><div class="technical-option-head"><span>${sourceLink(option.source)}</span><span class="catalogue-price">${amount}</span></div><h4>${esc(option.title)}</h4>${option.catalogueBadge?'<p class="catalogue-designation">Designação no catálogo: '+esc(option.catalogueBadge)+'</p>':''}<dl>${option.specifications.map(s=>`<div><dt>${esc(s.label)}</dt><dd>${esc(valueText(s.value,s.unit))}</dd></div>`).join('')}</dl><p class="option-limit">${esc(option.limits)}</p><p class="option-scope">${option.inclusion==='included'?'Inclusão declarada no catálogo':option.inclusion==='not-stated'?'Inclusão não declarada':'Opcional do catálogo'} · compatibilidade com esta casa por confirmar</p></article>`;}
function sourceFacts(){const facts=TECHNICAL_FACTS.filter(f=>!f.optionId&&f.category!=='Documentação pendente'&&f.category!=='Dimensões documentadas'&&f.category!=='Áreas');return facts.map(f=>`<article class="technical-fact" data-fact="${esc(f.id)}"><span class="eyebrow">${esc(f.category)}</span><h4>${esc(f.label)}</h4><p><strong>${esc(valueText(f.value,f.unit))}</strong></p><p>${esc(f.note)}</p>${sourceLink(f.source)}</article>`).join('');}
export function technicalSheetMarkup(configuration){
 const plan=getPlan(configuration),ledger=sourceLedger(configuration),layout=SOURCE_LAYOUTS.find(l=>l.id===configuration.layout),windows=plan.perimeter.flatMap(p=>p.holes).filter(h=>h.kind==='window').length;
 const sections=[...new Set(CATALOGUE_OPTIONS.map(o=>o.section))];
 return `<div class="technical-intro"><div><span class="eyebrow">FICHA DA SUA CONFIGURAÇÃO</span><h3>${esc(plan.label)} · ${configurationReference(configuration)}</h3><p>Fontes revistas em 11 de Setembro de 2026 · ${REVISION}</p></div><button class="outline" id="download-source-ledger">Guardar ficha e fontes ↓</button></div>
 <nav class="technical-index" aria-label="Índice da ficha técnica"><a href="#technical-dimensions">Dimensões</a><a href="#technical-options">Opcionais</a><a href="#technical-details">Materiais e detalhes</a><a href="#technical-motion">Expansão</a><a href="#technical-videos">Vídeos</a><a href="#technical-sources">Documentos</a></nav>
 <div class="technical-key-facts"><article><span>Dimensões nas plantas</span><strong>11,80 × 6,22 m</strong><small>Rectângulo exterior: 73,396 m²</small></article><article><span>Designação comercial</span><strong>72 m²</strong><small>Área útil certificada por fornecer</small></article><article><span>Distribuição seleccionada</span><strong>${plan.bedrooms} quarto${plan.bedrooms===1?'':'s'} · 1 banho</strong><small>${windows} janelas desenhadas no 3D · entrada de 2 folhas</small></article><article><span>Área livre da maquete</span><strong>≈ ${number(plan.areas.estimatedNet,1)} m²</strong><small>Antes das divisórias: ≈ ${number(plan.areas.internalEnvelope,3)} m²</small></article></div>
 <p class="technical-area-note">Áreas interiores calculadas na maquete com paredes de 100 mm e divisórias de 80 mm assumidas. A área antes das divisórias e a área livre não constam de um mapa certificado.</p><p class="technical-notice">As cotas escritas nas plantas prevalecem sobre a aparência das imagens. “Confirmado na fonte” identifica um dado do documento; os opcionais do catálogo genérico carecem de confirmação para esta configuração. ${layout?'Fonte da planta: '+esc(layout.source.sheet)+', '+esc(layout.source.cell)+'.':''}</p>
 <section id="technical-dimensions" class="technical-section"><h3>Dimensões, com origem e estado</h3><p>Um registo por medida. Os valores assumidos para a visualização são apresentados numa coluna própria.</p><div class="table-scroll dimension-scroll" tabindex="0" role="region" aria-label="Medidas, valores na fonte e valores da maquete"><table class="source-table dimension-table"><thead><tr><th scope="col">Medida</th><th scope="col">Valor na fonte</th><th scope="col">Valor na maquete</th><th scope="col">Estado</th><th scope="col">Origem e limite</th></tr></thead><tbody>${dimensionRows(ledger.dimensions)}</tbody></table></div><h4>Divergências a esclarecer</h4><ul class="source-list">${SOURCE_DIVERGENCES.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></section>
 <section id="technical-options" class="technical-section"><h3>Opcionais, especificação a especificação</h3><p>22 artigos documentados. Valores publicados na edição de 11/07/2026, com IVA de 23% incluído segundo o documento. Não são um orçamento nem um total da configuração; quantidades e compatibilidades serão confirmadas na proposta.</p><div class="evidence-links"><a class="outline" href="assets/opcionais-2026.pdf" target="_blank" rel="noopener">Abrir catálogo completo ↗</a><a class="outline" href="assets/product-r9/options-catalogue.json" download>Guardar os 22 opcionais ↓</a></div>${sections.map(section=>`<div class="technical-option-section"><h4 class="technical-category">${esc(section)}</h4><div class="technical-option-grid">${CATALOGUE_OPTIONS.filter(o=>o.section===section).map(optionCard).join('')}</div></div>`).join('')}</section>
 <section id="technical-details" class="technical-section"><h3>Materiais, vãos e detalhes das fontes</h3><p>71 amostras do catálogo e 32 fotografias de cozinha e casa de banho disponíveis na personalização. As referências mantêm as imagens originais; dimensões, implantação e escala física não cotadas permanecem estimadas.</p><div class="technical-fact-grid">${sourceFacts()}</div><h4>Camadas do modelo</h4><div class="source-cards">${LAYERS.map(([id,label,note])=>`<article><h4>${esc(label)}</h4><p>${esc(note)}</p></article>`).join('')}</div></section>
 <section id="technical-motion" class="technical-section"><h3>Expansão de dentro para fora</h3><div class="technical-motion"><img src="assets/expansao.png" alt="Sequência de expansão original com quatro quadros" loading="lazy" width="800" height="550"><div><p><strong>Animação dos quadros 2–3:</strong> as paredes longitudinais levantam-se com as janelas fixas aos painéis. Pode reproduzir, pausar, reiniciar e escolher qualquer posição.</p><p>O eixo longitudinal da maquete está a ±${number(WALL_RAISE.axisX,2)} m do centro, à altura de ${number(WALL_RAISE.axisY,2)} m. A folga visual de cobertura é de ${WALL_RAISE.roofClearance*1000} mm. Estes valores são estimativas geométricas.</p><p>Pisos e estrutura já abertos. Topos e interior omitidos durante a demonstração. Não estão documentados os eixos de fabrico, o recolhimento dos topos, os bloqueios nem a sequência completa de transporte e montagem.</p><button class="primary" data-explore-expansion>Explorar a animação ↗</button></div></div></section>
 <section id="technical-videos" class="technical-section"><h3>Os quatro vídeos originais</h3><p>Reprodução, pausa, capítulos e descarga revistos. Resolução nativa de 576 × 1 024 píxeis; os originais não foram alterados. São visitas a casas já abertas, sem demonstração do mecanismo de expansão.</p><div class="technical-video-grid">${REFERENCE_VIDEOS.videos.map(v=>`<article><h4>${esc(v.title)}</h4><p>${esc(Math.floor(v.duration_seconds/60)+':'+String(Math.floor(v.duration_seconds%60)).padStart(2,'0'))} · 576 × 1 024 px</p><p>${esc(v.variantNote)}</p><div class="evidence-links"><button class="outline" data-open-reference-video="${esc(v.id)}">Ver este vídeo ↗</button><a href="${esc(v.asset)}" download>Guardar original ↓</a></div></article>`).join('')}</div></section>
 <section id="technical-sources" class="technical-section"><h3>Documentos e verificações</h3><div class="source-cards">${SOURCES.map(s=>`<article><h4>${esc(s.label)}</h4><p>${esc(s.scope)}</p><small>${esc(s.locations)}</small><p>${esc(s.limits)}</p><a href="${esc(s.file)}" target="_blank" rel="noopener">Abrir documento ↗</a></article>`).join('')}</div><h4>Informação técnica ainda por fornecer</h4><ul class="pending-facts">${TECHNICAL_FACTS.filter(f=>f.category==='Documentação pendente').map(f=>'<li>'+esc(f.label)+'</li>').join('')}</ul><p>A tolerância numérica de 0,0000001 m serve apenas para comparações de cálculo. Não é uma tolerância de fabrico.</p><div class="evidence-links"><a class="outline" href="assets/product-r9/technical-inventory.json" download>Inventário técnico completo ↓</a><a class="outline" href="assets/product-r9/catalogue.json" download>Materiais e referências ↓</a><a class="outline" href="assets/evidence-r9/audit-report.html" target="_blank" rel="noopener">Verificação desta revisão ↗</a></div><details class="audit-history"><summary>Consultar revisões anteriores</summary><div class="evidence-links">${[8,7,6,5,4,3].map(r=>`<a href="assets/evidence-r${r}/audit-report.html" target="_blank" rel="noopener">Histórico R${r} ↗</a>`).join('')}</div></details></section>`;
}
